  function appendMappingPairs($parent, blockKey, title, entries, state) {
    var isPriority = blockKey === "priorities";
    var $head = $("<div/>")
      .addClass("ujg-esi-mapping-editor-head")
      .append(
        $("<h2/>").text(title),
        $("<button/>")
          .attr("type", "button")
          .addClass("ujg-esi-mapping-add")
          .text("+ Добавить")
          .on("click", function() {
            if (services && services.onMappingPairAdd) services.onMappingPairAdd(blockKey);
          })
      );
    var $table = $("<table/>").addClass("ujg-esi-mapping-table");
    var $tbody = $("<tbody/>");
    $table.append(
      $("<thead/>").append(
        $("<tr/>")
          .append($("<th/>").text("Excel значение"))
          .append($("<th/>").text("Jira значение"))
          .append($("<th/>").text(""))
      )
    );
    (entries || []).forEach(function(entry, index) {
      $tbody.append(
        $("<tr/>")
          .append($("<td/>").append(appendTextInput("ujg-esi-mapping-entry-excel", entry.excel, function(value) {
            if (services && services.onMappingPairChange) services.onMappingPairChange(blockKey, index, "excel", value);
          })))
          .append($("<td/>").append(isPriority
            ? appendSelect("ujg-esi-mapping-entry-jira ujg-esi-mapping-priority-select", entry.jira, priorityOptionRows(entry.jira, state), function(value) {
              if (services && services.onMappingPairChange) services.onMappingPairChange(blockKey, index, "jira", value);
            })
            : appendTextInput("ujg-esi-mapping-entry-jira", entry.jira, function(value) {
              if (services && services.onMappingPairChange) services.onMappingPairChange(blockKey, index, "jira", value);
            })
          ))
          .append($("<td/>").append(
            $("<button/>")
              .attr("type", "button")
              .addClass("ujg-esi-mapping-remove")
              .attr("title", "Удалить")
              .text("×")
              .on("click", function() {
                if (services && services.onMappingPairRemove) services.onMappingPairRemove(blockKey, index);
              })
          ))
      );
    });
    if (!(entries || []).length) {
      $tbody.append($("<tr/>").append($("<td/>").attr("colspan", "3").addClass("ujg-esi-mapping-empty").text("Нет значений мапинга.")));
    }
    $table.append($tbody);
    $parent.append($head, $table);
    if (blockKey === "modules") {
      var components = state.componentOptions || [];
      var message = state.componentsError || (!state.componentsLoaded
        ? "Компоненты Jira ещё не проверены."
        : "Компоненты проекта: " + (components.map(function(item) { return item.name; }).join(", ") || "нет"));
      $parent.append($("<p/>").addClass("ujg-esi-component-catalog").text(message));
      if (state.componentsLoaded) {
        function componentName(value) { return String(value || "").trim().replace(/\s+/g, " ").toLocaleLowerCase(); }
        function matchingComponent(entry) {
          return components.filter(function(component) { return componentName(component.name) === componentName(entry.jira); })[0];
        }
        var missing = (entries || []).filter(function(entry) {
          return entry.jira && !matchingComponent(entry);
        });
        if (missing.length) $parent.append($("<p/>").addClass("ujg-esi-component-warning")
          .text("Не найдены в проекте Jira: " + missing.map(function(entry) { return entry.jira; }).join(", ")));
        var renamed = (entries || []).filter(function(entry) {
          var match = matchingComponent(entry);
          return match && entry.jira !== match.name;
        });
        if (renamed.length) $parent.append($("<p/>").addClass("ujg-esi-component-name-warning")
          .text("Уточните точное имя компонента: " + renamed.map(function(entry) { return entry.jira + " → " + matchingComponent(entry).name; }).join(", ")));
      }
    }
  }

